"""Fuzz with deep peeling structures and larger cores."""
import json, random, subprocess, sys, math
sys.path.insert(0, '/workspace/tmp')
sys.path.insert(0, '/workspace/submission')
import ref
from fuzz import equal


def gen(seed):
    rnd = random.Random(seed)
    nn = rnd.randint(4, 12)
    nodes = list(range(1, nn + 1))
    style = rnd.randint(0, 3)
    rib = []
    if style == 0:
        # sliding windows over a chain -> deep peeling
        chain = nodes
        w = rnd.randint(2, min(6, nn))
        for s in range(0, max(1, nn - w + 1)):
            p = chain[s:s + w]
            if len(p) >= 2:
                rib.append({'path': list(p), 'count': rnd.randint(1, 4)})
    elif style == 1:
        # protector chains
        k = rnd.randint(1, 6)
        for j in range(k):
            a = rnd.choice(nodes)
            b = rnd.choice(nodes)
            while b == a:
                b = rnd.choice(nodes)
            c = rnd.choice(nodes)
            while c in (a, b):
                c = rnd.choice(nodes)
            d = rnd.choice(nodes)
            while d in (a, b, c):
                d = rnd.choice(nodes)
            p = [a, b, c, d]
            if rnd.random() < 0.5:
                p = p[::-1]
            rib.append({'path': p, 'count': rnd.randint(1, 4)})
    elif style == 2:
        # random walks
        for _ in range(rnd.randint(2, 10)):
            ln = rnd.randint(2, min(8, nn))
            p = []
            cur = rnd.choice(nodes)
            for _ in range(ln):
                p.append(cur)
                cur = rnd.choice(nodes)
                while cur in p:
                    if rnd.random() < 0.7:
                        cur = rnd.choice(nodes)
                    else:
                        cur = rnd.randint(nn + 1, nn + 5)
            rib.append({'path': p, 'count': rnd.randint(1, 4)})
    else:
        # random simple paths
        for _ in range(rnd.randint(2, 10)):
            ln = rnd.randint(2, min(8, nn))
            p = rnd.sample(nodes, ln)
            rib.append({'path': p, 'count': rnd.randint(1, 4)})
    ixps = []
    agg = {}
    for rec in rib:
        p = ref.normalize(rec['path'], set(ixps))
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        agg[tuple(p)] = agg.get(tuple(p), 0) + rec['count']
    if not agg:
        return None
    final, rounds = ref.ref_peel(agg)
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(ref.canon(p[i], p[i + 1]))
    if len(core) > 9 or not core:
        return None
    occs = ref.ref_occurrences(final)
    adj = ref.scope_graph(occs, core)
    order = ref.find_order(adj)
    if order is None:
        return None
    order = [[u, v] for (u, v) in order]
    pool = set(core) | set(rounds)
    priors, declared, queries = [], [], []
    usedp, usedd = set(), set()
    for _ in range(rnd.randint(0, 6)):
        if not pool:
            break
        l = rnd.choice(sorted(pool))
        if l in usedp:
            continue
        usedp.add(l)
        w = [rnd.randint(0, 5) for _ in range(3)]
        if sum(w) == 0:
            w[rnd.randint(0, 2)] = 1
        pair = list(l) if rnd.random() < 0.5 else [l[1], l[0]]
        priors.append({'link': pair, 'weights': w})
    for _ in range(rnd.randint(0, 5)):
        if not pool:
            break
        l = rnd.choice(sorted(pool))
        if l in usedd:
            continue
        usedd.add(l)
        pair = list(l) if rnd.random() < 0.5 else [l[1], l[0]]
        declared.append({'link': pair, 'rel': rnd.choice(['c2p', 'p2p', 'p2c'])})
    for i in range(rnd.randint(0, 6)):
        ln = rnd.randint(0, 8)
        base = [rnd.choice(nodes + [901, 902]) for _ in range(ln)]
        raw = []
        for x in base:
            raw.append(x)
            if rnd.random() < 0.25:
                raw.append(x)
        th = sorted([rnd.randint(0, 5), rnd.randint(1, 5)])
        queries.append({'id': 's%d_%d' % (seed, i), 'path': raw,
                        'threshold': th})
    return {'version': 1, 'ixps': ixps, 'rib': rib, 'priors': priors,
            'declared': declared, 'order': order, 'queries': queries}


def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    fails = 0
    tested = 0
    zp = 0
    rounds_seen = {}
    for seed in range(lo, hi):
        doc = gen(seed)
        if doc is None:
            continue
        expected = ref.ref_solve(doc)
        if expected.get('error') == 'zero-partition':
            zp += 1
        raw = json.dumps(doc).encode()
        got = subprocess.run([sys.executable, '-I',
                              '/workspace/submission/main.py'],
                             input=raw, capture_output=True, cwd='/workspace')
        try:
            actual = json.loads(got.stdout.decode())
        except Exception:
            print('seed', seed, 'BAD OUTPUT', got.stdout[:200], got.stderr[:400])
            fails += 1
            continue
        if got.returncode != 0 or not equal(expected, actual):
            fails += 1
            print('seed', seed, 'MISMATCH')
            print(' input:', json.dumps(doc))
            print(' expected:', json.dumps(expected))
            print(' actual  :', json.dumps(actual))
            if fails > 2:
                break
        else:
            for l in expected.get('links', []):
                rounds_seen[l['round']] = rounds_seen.get(l['round'], 0) + 1
        tested += 1
    print('tested', tested, 'fails', fails, 'zero-partition', zp,
          'round histogram', dict(sorted(rounds_seen.items())))
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
